[Approach 2]  Using Breadth-First Search - O(m * n) Time and O(m * n) SpaceThe idea is the same as DFS, but instead of using recursion, we use Breadth-First Search (BFS) because it avoids recursion overhead. In BFS, we use a queue and traverse level by level. We start from the given pixel, change its color to the new one, and push it into the queue. Then, for each pixel we pop, we check all four adjacent cells—if any neighbor has the same old color, we update it with the new color and add it to the queue. This continues until all connected pixels are updated.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
#include <queue>
using namespace std;
//Driver Code Ends


vector<vector<int>> floodFill(vector<vector<int>>& img, int sr, 
    int sc, int newColor) {

    // If the starting pixel already has the new color
    if (img[sr][sc] == newColor) {
        return img;
    }

    // Direction vectors for traversing 4 directions
    vector<pair<int, int>> dir = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    queue<pair<int, int>> q;
    int oldColor = img[sr][sc];
    q.push({sr, sc});

    // Change the color of the starting pixel
    img[sr][sc] = newColor;

    // Perform BFS
    while (!q.empty()) {
        pair<int, int> front = q.front();
        int x = front.first, y = front.second;
        q.pop();

        // Traverse all 4 directions
        for (pair<int, int>& it : dir) {
            int nx = x + it.first;
            int ny = y + it.second;

            // Check boundary conditions and color match
            if (nx >= 0 && nx < img.size() && 
                ny >= 0 && ny < img[0].size() && 
                img[nx][ny] == oldColor) {
                img[nx][ny] = newColor;
                q.push({nx, ny});
            }
        }
    }

    return img;
}


