    //Driver Code Starts
using System;
using System.Collections.Generic;

class GFG {
//Driver Code Ends

    public static int[,] floodFill(int[,] img, int sr,
        int sc, int newColor) {

        // If the starting pixel already has the new color
        if (img[sr, sc] == newColor)
            return img;

        // Direction vectors for traversing 4 directions
        int[,] dir = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        Queue<(int, int)> q = new Queue<(int, int)>();
        int oldColor = img[sr, sc];
        q.Enqueue((sr, sc));

        // Change the color of the starting pixel
        img[sr, sc] = newColor;

        int n = img.GetLength(0);
        int m = img.GetLength(1);

        // Perform BFS
        while (q.Count > 0) {
            var (x, y) = q.Dequeue();

            // Traverse all 4 directions
            for (int i = 0; i < 4; i++) {
                int nx = x + dir[i, 0];
                int ny = y + dir[i, 1];

                // Check boundary conditions and color match
                if (nx >= 0 && nx < n &&
                    ny >= 0 && ny < m &&
                    img[nx, ny] == oldColor) {
                    img[nx, ny] = newColor;
                    q.Enqueue((nx, ny));
                }
            }
        }

        return img;
    }


//Driver Code Starts
    static void Main() {
        int[,] img = {
            {1, 1, 1, 0},
            {0, 1, 1, 1},
            {1, 0, 1, 1}
        };

        int sr = 1, sc = 2;
        int newColor = 2;

        int[,] result = floodFill(img, sr, sc, newColor);

        int n = result.GetLength(0);
        int m = result.GetLength(1);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Console.Write(result[i, j] + " ");
            }
            Console.WriteLine();
        }
    }
}

