        const [x, y] = q.shift();

        // Traverse all 4 directions
        for (const it of dir) {
            const nx = x + it[0];
            const ny = y + it[1];

            // Check boundary conditions and color match
            if (nx >= 0 && nx < img.length &&
                ny >= 0 && ny < img[0].length &&
                img[nx][ny] === oldColor) {
                img[nx][ny] = newColor;
                q.push([nx, ny]);
            }
        }
